const binaryData = $binary?.data;
let transcript = '';
if (binaryData?.data) {
  transcript = Buffer.from(binaryData.data, 'base64').toString('utf-8').substring(0, 6000);
}

const systemPrompt = [
  'You are processing call transcripts and WhatsApp exports for WHEN Travel, a travel savings coaching platform based in India.',
  'Return ONLY a valid JSON object — no markdown, no preamble.',
  '',
  '{',
  '  "name": "client first name",',
  '  "phone": "WhatsApp/phone number if mentioned, else null",',
  '  "source_city": "city they are from if mentioned, else null",',
  '  "time_to_travel": "when they want to travel e.g. March 2026 or 6 months, else null",',
  '  "budget_range": "total trip budget as a string e.g. 1.5L or 80000, else null",',
  '  "blockers_pain_point": "their main financial or emotional blocker, else null",',
  '  "jtbd": "transformation or value they want from this trip, else null",',
  '  "journey_stage": "Discovery Done or Plan Delivered or Active Saver or Milestone Unlocked or Trip Completed"',
  '}',
  '',
  'Journey stage rules:',
  '- Discovery Done: first intake call, no plan delivered yet',
  '- Plan Delivered: coach mentioned or sent a savings plan',
  '- Active Saver: client actively tracking savings',
  '- Milestone Unlocked: flights or accommodation booked',
  '- Trip Completed: trip has already happened'
].join('\n');

const requestBody = JSON.stringify({
  model: 'claude-haiku-4-5-20251001',
  max_tokens: 512,
  system: systemPrompt,
  messages: [{ role: 'user', content: transcript || 'No transcript content available.' }]
});

return { json: { requestBody, filename: $('Loop Docs').item.json.name } };

const responseText = $input.item.json.content[0].text;
const cleaned = responseText
  .replace(/```json\n?/g, '')
  .replace(/```\n?/g, '')
  .trim();

const defaults = {
  name: null, phone: null, source_city: null,
  time_to_travel: null, budget_range: null,
  blockers_pain_point: null, jtbd: null, journey_stage: null
};

try {
  const extracted = JSON.parse(cleaned);
  return { json: { ...defaults, ...extracted } };
} catch (e) {
  return { json: defaults };
}

const d = $('Parse Response').item.json;
const allRecords = $('Fetch All People').item.json.data || [];
const filename = $('Loop Docs').item.json.name || '';

const fallbackName = filename.split('_Session')[0].replace(/_/g, ' ').trim();
const personName = (d.name && d.name.trim()) ? d.name.trim() : fallbackName;

function txt(v) {
  return (v !== null && v !== undefined && String(v).trim() !== '')
    ? [{ value: String(v).trim() }]
    : undefined;
}

function buildValues() {
  const v = {};
  if (personName) v.name = [{ first_name: personName, last_name: '', full_name: personName }];

  const source_city      = txt(d.source_city);         if (source_city)      v.source_city      = source_city;
  const trip_timeline    = txt(d.time_to_travel);      if (trip_timeline)    v.trip_timeline    = trip_timeline;
  const trip_budget      = txt(d.budget_range);        if (trip_budget)      v.trip_budget      = trip_budget;
  const pain_points      = txt(d.blockers_pain_point); if (pain_points)      v.pain_points      = pain_points;
  const value_points     = txt(d.jtbd);                if (value_points)     v.value_points     = value_points;
  const journey_stage    = txt(d.journey_stage);       if (journey_stage)    v.journey_stage    = journey_stage;

  if (d.phone && String(d.phone).trim()) {
    v.phone_numbers = [{ phone_number: String(d.phone).trim(), country_code: 'IN' }];
  }

  return v;
}

const existing = allRecords.find(r => {
  const nameArr = r.values && r.values.name;
  if (!nameArr || !nameArr[0]) return false;
  return (nameArr[0].full_name || '').toLowerCase() === (personName || '').toLowerCase();
});

const values = buildValues();

if (!existing) {
  return { json: { isNew: 'true', body: JSON.stringify({ data: { values } }) } };
}

return {
  json: { isNew: 'false', recordId: existing.id.record_id, body: JSON.stringify({ data: { values } }) }
};
